'use strict';
const localSlots=new Set(['chapter-kicker','chapter-title','chapter-lede','chapter-controls','insight','chapter-source','figure-scope','measure-tag','chart','chart-key','figure-note','chapter-takeaway','selection-detail']);
const $=id=>localSlots.has(id)?document.querySelector(`[data-chapter-panel="${state.chapter}"] [data-slot="${id}"]`):document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const words=s=>String(s).replace(/([a-z])(?=\d)/g,'$1 ').replace(/(\d)(?=[A-Za-z]{2,})/g,'$1 ').replace(/([a-z])(?=HK\$)/g,'$1 ');
function normalizeText(root){const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){if(['SCRIPT','STYLE'].includes(n.parentElement?.tagName))continue;const v=words(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v;}}
const C=['#bc573b','#177b75','#7563a2','#946b1d','#3e7697','#986575'];
const purpose=[{id:'leisure',name:'Leisure',short:'Leisure',value:45.7,color:C[0],description:'Leisure was the largest reported purpose in this historical trip mix. The category is broader than shopping.'},{id:'visits',name:'Visiting relatives and friends',short:'Visiting relatives & friends',value:28.8,color:C[1],description:'Visits to relatives and friends were a substantial part of cross-boundary travel. The survey did not measure the strength of those relationships.'},{id:'business',name:'Business',short:'Business',value:14.4,color:C[2],description:'Business trips were recorded separately from travelling to a usual place of work.'},{id:'work',name:'Work',short:'Work',value:5.2,color:C[3],description:'Work was one of several reported purposes. These passenger movements do not count distinct workers.'},{id:'other',name:'Other purposes',short:'Other purposes',value:5.9,color:C[4],description:'The remaining purpose categories are grouped as other purposes in this comparison.'}];
const sources={
 purpose:{title:'Different reasons to cross',by:'Hong Kong Planning Department',period:'16–29 November 2017',measure:'Average daily one-way passenger movements, both directions',population:'People usually living in Hong Kong; trips between Hong Kong and all Mainland destinations. Land, sea and air; drivers excluded.',url:'https://www.pland.gov.hk/file/planning_studies/comp_s/nbsb2021/en/NBSB2021.pdf',location:'2021 report, Table 3.7, printed page 51, 2017 column',notes:'319,800 is a survey-period daily estimate, not a count of unique people or an annual average. A round trip counts twice. The five percentages are a historical purpose composition. They cannot be treated as a current Shenzhen-only estimate or joined to the separate Shenzhen destination share.'},
 survey:{title:'Northbound consumption and care',by:'HKFYG Youth Research Centre',period:'9–14 November 2024; preceding-year recall',measure:'Counts and percentages in an interview sample',population:'600 Hong Kong residents aged 18–74, intercepted at ten randomly selected transport nodes. Random locations do not establish a probability sample of residents.',url:'https://yrc.hkfyg.org.hk/wp-content/uploads/sites/56/2024/12/YI079_Report-1.pdf#page=54',location:'Tables 5.6–5.14, printed pages 42–46; methods printed page 4',notes:'Frequency uses n=600. Activities use n=486 northbound consumers and allow multiple answers. Medical motivations use n=181 users; non-use reasons use n=419. Reasons allow up to three selections. The source prints 40.3% beside 182/600 for monthly consumption; the count gives 30.3%, which we use. The nearly-daily category is printed as a dash; no value is displayed separately here. No respondent-level records or cross-tab between activities and destinations are available in this story.'},
 money2025:{title:'Where health-voucher pilot claims were recorded',by:'Hong Kong Department of Health',period:'Calendar year 2025',measure:'Claim transactions and claimed amounts in HK dollars',population:'19 pilot providers, including 12 that joined during 2025. Existing HKU–Shenzhen Hospital service points are outside this table.',url:'https://www.dh.gov.hk/english/budget/files/2026-27_eng.pdf#page=275',location:'Reply HHB248, part 2, printed pages 273–274',notes:'Published totals are 51,384 transactions and HK$51.811 million. Rounded provider amounts sum to HK$51.812 million; percentages use the published total. Providers had different participation periods and service mixes. These are distributions of recorded claims, not rankings of performance, profit, patient numbers or health benefit.'},
 money2024:{title:'The first year of the expanded voucher pilot',by:'Hong Kong Department of Health',period:'Each provider’s start date through 31 December 2024',measure:'Claim transactions and rounded claimed amounts',population:'Seven newly added pilot providers; participation began on different dates between June and September 2024. Existing HKU–Shenzhen Hospital points excluded.',url:'https://www.dh.gov.hk/english/budget/files/2025-26_eng.pdf#page=194',location:'Reply HHB246, printed pages 190–191',notes:'The seven published provider amounts sum to HK$19.782 million, across 15,468 transactions. This inception-period snapshot has different providers and exposure from calendar 2025. Changes between views do not isolate a policy effect. The separate residence table must not be linked to provider choice.'},
 ties:{title:'Mobility, belongingness and schooling experiences',by:'Chan, Chiu, Yang & Ngan (2020)',period:'Published 2020; field dates not verified in the checked summary',measure:'Observational associations using factor analysis and structural equation modelling',population:'417 cross-border schoolchildren; Hong Kong permanent residents living on the Mainland.',url:'https://doi.org/10.1016/j.childyouth.2020.104870',location:'Author research summary, pages 7–8',notes:'Better local-peer relations, having friends mostly from Hong Kong, and extracurricular participation were associated with stronger belonging. Commuting hours were not statistically significant in this sample. This does not prove zero effect or a causal ranking. Selected children cannot represent all shoppers, workers or Singapore–Johor users. The visual uses equal-size conceptual nodes, not effect sizes.',extra:'https://chineseedmobilities.com/wp-content/uploads/2020/04/nrcem-newsletter_issue-20_april-2020-2.pdf#page=7'},
 wellbeing:{title:'A different question: comparative wellbeing',by:'Applied Research in Quality of Life (2025)',period:'School-based data collected in 2016–17',measure:'Between-group comparisons with propensity-score matching',population:'Hong Kong pupils and Hong Kong children attending Shenzhen schools; groups and outcomes differ from the 417-student belonging study.',url:'https://link.springer.com/article/10.1007/s11482-025-10481-7',location:'Methods and comparative results',notes:'The study found little evidence of disadvantage for cross-border students on its wellbeing comparisons after matching observed characteristics. This is not a demonstration of equivalence. Matching cannot rule out unmeasured selection. Do not pool these results with within-group belonging associations or assume the underlying samples are independent.'},
 accountability:{title:'Access, money and accountability',by:'Hong Kong Department of Health',period:'Complaints received through December 2025; investigation status at 28 February 2026',measure:'Described programme arrangements and complaint status',population:'Greater Bay Area health-voucher pilot',url:'https://www.dh.gov.hk/english/budget/files/2026-27_eng.pdf#page=145',location:'Reply HHB217, part 4',notes:'Six complaints had been received cumulatively. Four investigations were completed without finding agreement noncompliance or aberrant claim patterns; two remained pending at the stated date. This is neither a complaint rate nor a clinical-quality judgment. Provider agreements, auditing and complaint channels are documented arrangements; their existence does not establish effective representation or belonging.'}
};
sources.plans={title:'Connections planned on different clocks',by:'Hong Kong SAR Government; Shenzhen Municipal Government',period:'Plans published in 2025–2026; transport targets 2027–2035',measure:'Planned spatial structure and commissioning milestones',population:'Hong Kong Northern Metropolis rail projects and Shenzhen core functional centres',url:'https://www.info.gov.hk/gia/general/202609/16/P2026091600196.htm',extra:'https://www.sz.gov.cn/cn/xxgk/zfxxgj/ghjh/csgh/zt/content/post_12013111.html',location:'Hong Kong First Five-Year Plan, Part 3, Table 27; Shenzhen spatial plan, Articles 24–26',notes:'All four rail dates are commissioning targets, not completed connections. Shenzhen retains Luohu among four core functional centres. The diagram uses equal unweighted marks and is not a geographic map, a flow estimate or a travel-time model. Future effects on access and belonging are unmeasured here.'};

sources.money2025.extra='https://www.info.gov.hk/gia/general/202606/17/P2026061700586p.htm';sources.money2025.notes+=' A 17 June 2026 reply reports later cumulative pilot use through May 2026. Its period and reporting definitions differ; it is not substituted for these annual provider shares.';

const chapters=[
 {id:'routines',name:'Routines',color:C[0],kicker:'01 / A historical travel snapshot',title:'Different reasons to cross.',lede:'Work is one part of cross-border life. This 2017 survey also recorded the trips people made for leisure, family and friends.',scope:'2017 · HK–all Mainland · people usually living in Hong Kong',tag:'Passenger trips',source:'purpose',takeaway:'Leisure and visits made up 74.5% of this historical trip mix.'},
 {id:'people',name:'People',color:C[1],kicker:'02 / Listen to an interview sample',title:'How often do people go north?',lede:'In November 2024, researchers spoke to 600 adults at transport stops. Their answers included frequent northbound consumption—and no northbound consumption at all.',scope:'November 2024 · HKFYG transport-node interview sample',tag:'Survey responses',source:'survey',takeaway:'Keep non-users in the picture. In this sample, 114 of 600 reported no northbound consumption in the preceding year.'},
 {id:'care',name:'Care',color:C[2],kicker:'03 / A closer look at everyday care',title:'Care depends on more than price.',lede:'Among medical-service users, 85.1% named lower costs. Among non-users, 51.3% named unfamiliarity. Different experiences shape whether an opportunity feels usable.',scope:'November 2024 · reported reasons · up to three selections',tag:'Different groups',source:'survey',takeaway:'Users most often named lower costs; non-users most often named unfamiliarity.'},
 {id:'money',name:'Public support',color:C[3],kicker:'04 / Trace a real institutional arrangement',title:'Follow where public support goes.',lede:'Hong Kong’s elderly health-voucher pilot lets eligible older residents use their vouchers at designated Mainland providers. In 2025, C.K.J, a Shenzhen dental hospital, recorded 44.5% of transactions and 70.5% of claimed money.',scope:'2025 · 19 pilot providers · unequal participation periods',tag:'Administrative data',source:'money2025',takeaway:'Switch the measure. The distribution of claimed money is different from the distribution of transactions.'},
 {id:'ties',name:'Belonging',color:C[4],kicker:'05 / Ask what movement leaves unmeasured',title:'Where does belonging enter?',lede:'Researchers have asked cross-border students about friendships, participation and feeling at home. Those answers need their own evidence.',scope:'Observational research · selected groups · conceptual links',tag:'Not effect sizes',source:'ties',takeaway:'For the next field visit: who gains, who carries costs, and who gets a say in the arrangements?'}
];
const state={chapter:0,selected:null,peopleView:'frequency',careView:'overview',moneyView:'overview',moneyMetric:'amount',year:2025,allProviders:false,tiesView:'findings',motion:!matchMedia('(prefers-reduced-motion: reduce)').matches};
function syncMotion(){document.body.classList.toggle('no-motion',!state.motion);document.documentElement.classList.toggle('no-motion',!state.motion);$('motion-button').textContent=state.motion?'Motion on':'Motion off';$('motion-button').setAttribute('aria-pressed',String(!state.motion));if(!state.motion&&document.getAnimations)document.getAnimations().forEach(a=>a.cancel());}
syncMotion();
let DATA={survey:[],providers2024:[],providers2025:[]};
const num=n=>Number(n).toLocaleString('en-US');
const pct=(n,d)=>(100*n/d).toFixed(1)+'%';
const t=(x,y,text,size=16,cls='',extra='')=>`<text x="${x}" y="${y}" font-size="${size}" class="${cls}" ${extra}>${esc(text)}</text>`;
function wrap(text,max=23){const words=String(text).split(' '),lines=[];let row='';for(const word of words){if((row+' '+word).trim().length>max&&row){lines.push(row);row=word;}else row+=(row?' ':'')+word;}if(row)lines.push(row);return lines;}
function multi(x,y,text,max=23,size=16,color=''){return `<text x="${x}" y="${y}" font-size="${size}" ${color?`style="fill:${color}"`:''}>${wrap(text,max).map((l,i)=>`<tspan x="${x}" dy="${i?size*1.25:0}">${esc(l)}</tspan>`).join('')}</text>`;}
function svg(content,w,h,desc){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="group" aria-labelledby="viz-title-${state.chapter} viz-desc-${state.chapter}"><title id="viz-title-${state.chapter}">${esc(chapters[state.chapter].title)}</title><desc id="viz-desc-${state.chapter}">${esc(desc)}</desc>${content}</svg>`;}
function group(id,label,content){return `<g class="mark-group" tabindex="0" role="button" data-select="${esc(id)}" aria-label="${esc(words(label))}" aria-pressed="${state.selected===String(id)}"><title>${esc(label)}</title>${content}</g>`;}
function segment(action,values,current){return `<div class="segment" role="group" aria-label="${esc(action)}">${values.map(([v,label])=>`<button data-action="${action}" data-value="${v}" aria-pressed="${String(current)===String(v)}">${label}</button>`).join('')}</div>`;}
function key(items){$('chart-key').innerHTML=items.map(i=>`<button data-select="${esc(i.id)}" aria-pressed="${state.selected===String(i.id)}" style="--key:${i.color||C[0]}">${esc(i.label)}</button>`).join('')+`<button class="plain" data-clear>Reset focus</button>`;}
function controls(){let html='';if(state.chapter===1)html=segment('peopleView',[['frequency','Frequency'],['activities','Activities']],state.peopleView);if(state.chapter===2)html=segment('careView',[['overview','Two perspectives'],['users','All user reasons'],['nonusers','All non-user reasons']],state.careView);if(state.chapter===3){html=segment('moneyView',[['overview','Compare measures'],['providers','Provider detail']],state.moneyView);if(state.moneyView==='providers')html+=segment('moneyMetric',[['amount','Claimed money'],['count','Transactions']],state.moneyMetric)+`<div class="year-control">Period ${[2024,2025].map(y=>`<button data-action="year" data-value="${y}" aria-pressed="${state.year===y}">${y}${y===2024?' · inception':''}</button>`).join('')}<button data-action="allProviders" data-value="${!state.allProviders}">${state.allProviders?'Show fewer':'Show all providers'}</button></div>`;}if(state.chapter===4)html=segment('tiesView',[['findings','Belonging'],['plans','Planned connections'],['questions','Next questions']],state.tiesView);$('chapter-controls').innerHTML=html;}
function sourceKey(){if(state.chapter===4&&state.tiesView==='plans')return 'plans';return state.chapter===3?'money'+state.year:state.chapter===4&&state.tiesView==='questions'?'accountability':chapters[state.chapter].source;}
function render(){const c=chapters[state.chapter];const panel=document.querySelector(`[data-chapter-panel="${state.chapter}"]`);panel.style.setProperty('--active',c.color);$('selection-detail').hidden=true;$('chapter-kicker').textContent=c.kicker;$('chapter-title').textContent=c.title;$('chapter-lede').textContent=state.chapter===3&&state.moneyView==='providers'&&state.year===2024?'In the elderly health-voucher pilot, these seven providers joined on different dates in 2024. This snapshot covers each provider’s start date through year end, rather than a full year for every provider.':c.lede;$('figure-scope').textContent=c.scope;$('measure-tag').textContent=c.tag;$('chapter-takeaway').textContent=c.takeaway;controls();const w=Math.max(290,Math.round($('chart').clientWidth));[renderPurpose,renderPeople,renderCare,renderMoney,renderTies][state.chapter](w);renderInsight();applySelection();normalizeText(panel);}

function renderPurpose(w){const small=w<600,h=small?590:560,x0=16,x1=w*(small?.53:.63),span=300,y0=105,targets=[62,169,276,383,490];let s=t(x0,42,'100% of trips',12,'muted'),offset=0;purpose.forEach((p,k)=>{const thick=span*p.value/100,sy=y0+offset,endThick=.9*p.value,ey=targets[k]-endThick/2,c1=x0+(x1-x0)*.43,c2=x0+(x1-x0)*.57;const path=`M ${x0} ${sy} C ${c1} ${sy}, ${c2} ${ey}, ${x1} ${ey} L ${x1} ${ey+endThick} C ${c2} ${ey+endThick}, ${c1} ${sy+thick}, ${x0} ${sy+thick} Z`;const labelX=x1+16,max=small?13:24,size=small?14:17,ly=targets[k]-12;let content=`<path class="ribbon" d="${path}" fill="${p.color}" opacity=".78"/>`+multi(labelX,ly,p.short,max,size)+t(labelX,ly+(wrap(p.short,max).length-1)*size*1.25+32,p.value.toFixed(1)+'%',small?25:30,'serif',`style="fill:${p.color}"`);s+=group(p.id,`${p.name}: ${p.value}% of trips`,content);offset+=thick;});s+=t(16,small?570:548,'Ribbon thickness = share of trips',12,'muted');$('chart').innerHTML=svg(s,w,h,'Five filled ribbons proportional to trip shares at both ends. Leisure45.7%, visits28.8%, business14.4%, work5.2%, other5.9%.');key(purpose.map(p=>({id:p.id,label:p.name,color:p.color})));$('figure-note').innerHTML='<strong>16–29 November 2017.</strong> Historical HK–all Mainland travel by people usually living in Hong Kong. These are movements, not unique people; a round trip counts twice.';}

function frequencyGroups(){return[{id:'monthly',name:'At least monthly',count:316,color:C[1],note:'316 interviewees reported northbound consumption at least monthly during the preceding year.'},{id:'less',name:'Less than monthly',count:170,color:C[4],note:'170 interviewees reported northbound consumption, but less often than monthly.'},{id:'none',name:'None in the past year',count:114,color:C[0],note:'114 interviewees reported no northbound consumption in the preceding year. This does not tell us whether they crossed for other reasons.'}];}
function renderPeople(w){if(state.peopleView==='activities'){const rows=DATA.survey.filter(r=>r.table==='5.7');bars(rows,w,C[1],r=>r.record_id,r=>shortActivity(r.category));$('figure-scope').textContent='November 2024 · 486 northbound consumers · multiple responses';$('measure-tag').textContent='Not spending shares';$('figure-note').innerHTML='<strong>Each bar answers a separate question.</strong> People could name several main activities, so the percentages do not add to100%. These are activity responses, not shares of money or trips.';key([]);return;}const small=w<600,gs=frequencyGroups(),cols=small?32:50,step=(w-32)/cols,rowGap=small?165:155,h=rowGap*3+40;let s='';gs.forEach((g,k)=>{const y=45+k*rowGap;let inside=t(12,y,g.name,16)+t(12,y+27,`${g.count} / 600 · ${pct(g.count,600)}`,22,'serif',`style="fill:${g.color}"`);for(let j=0;j<g.count;j++){inside+=`<circle class="dot" cx="${16+(j%cols)*step}" cy="${y+48+Math.floor(j/cols)*8}" r="2.5" fill="${g.color}"/>`;}inside+=`<rect class="hit-outline" x="4" y="${y-23}" width="${w-8}" height="${rowGap-10}" fill="#fff" fill-opacity="0" pointer-events="all" stroke="transparent" rx="8"/>`;s+=group(g.id,`${g.count} of 600: ${g.name}`,inside);});$('chart').innerHTML=svg(s,w,h,'600 equal dots in three aligned rows: 316 at least monthly, 170 less often, 114 none. One dot is one respondent count, not a linked individual record.');key(gs.map(g=>({id:g.id,label:g.name,color:g.color})));$('figure-note').innerHTML='<strong>One dot = one respondent.</strong> 600 interviews at transport nodes, ages 18–74. These aggregate counts cannot be extrapolated to all Hong Kong residents.';}
function shortActivity(s){return({'Shopping malls and entertainment':'Malls & entertainment','Shopping e.g. food and household goods':'Food & household shopping','Medical services e.g. examinations and treatment':'Medical examinations & treatment','Medicines and health products':'Medicines & health products'}[s]||s);}
function bars(rows,w,color,getId=r=>r.record_id,getLabel=r=>r.category){const small=w<670,rowH=small?88:61,h=rows.length*rowH+55,x0=small?12:Math.min(290,w*.37),bw=small?w-85:w-x0-88;let s='';for(const tick of[0,25,50,75,100]){const x=x0+bw*tick/100;s+=`<line class="grid" x1="${x}" y1="25" x2="${x}" y2="${h-25}"/>`+t(x,16,tick+'%',12,'muted',`text-anchor="${tick===0?'start':tick===100?'end':'middle'}"`);}rows.forEach((r,i)=>{const y=i*rowH+49,p=100*r.count/r.denominator,by=small?y+(wrap(getLabel(r),36).length-1)*18.75+18:y-7;let row=multi(small?12:4,y,getLabel(r),small?36:25,small?15:15)+`<rect class="data-bar" x="${x0}" y="${by}" width="${(bw*p/100).toFixed(2)}" height="${small?9:11}" rx="1" fill="${color}" style="animation-delay:${i*.035}s"/>`+t(x0+bw+12,by+10,p.toFixed(1)+'%',small?16:17,'',`style="fill:${color}"`)+t(x0+bw+12,by+28,`${r.count}/${r.denominator}`,12,'muted');row+=`<rect x="0" y="${y-23}" width="${w}" height="${rowH}" fill="#ffffff" fill-opacity="0" pointer-events="all"/>`;s+=group(getId(r),`${getLabel(r)}: ${r.count} of${r.denominator}, ${p.toFixed(1)}%`,row);});$('chart').innerHTML=svg(s,w,h,'Independent horizontal bars, zero to100percent. Each row states its count and denominator. Multiple answers may overlap.');}
function renderCareOverview(w){const small=w<500,pw=small?w:(w-25)/2,h=small?730:420;let s='';const groups=[{tab:'5.13',count:181,title:'People who used care',color:C[2]},{tab:'5.14',count:419,title:'People who did not',color:C[0]}];groups.forEach((g,k)=>{const x=small?0:k*(pw+25),y=small?k*355:0,bw=pw-25,rows=DATA.survey.filter(r=>r.table===g.tab).slice(0,3);s+=`<rect x="${x}" y="${y+3}" width="${pw}" height="334" rx="14" fill="${g.color}" opacity=".045"/>`+t(x+10,y+37,g.title,small?19:18,'serif')+t(x+10,y+62,`${g.count} respondents · up to 3 answers`,12,'muted');rows.forEach((r,i)=>{const yy=y+113+i*76,p=100*r.count/r.denominator;let label=r.category;if(label.length>37)label=label.replace('medical services','care').replace('Mainland','Mainland');let marks=multi(x+10,yy,label,small?38:27,13)+`<rect x="${x+10}" y="${yy+28}" width="${bw}" height="7" fill="${g.color}" opacity=".1"/><rect class="data-bar" x="${x+10}" y="${yy+28}" width="${bw*p/100}" height="7" fill="${g.color}"/>`+t(x+10,yy+57,`${p.toFixed(1)}% · ${r.count}/${r.denominator}`,13,'',`style="fill:${g.color}"`)+`<rect x="${x}" y="${yy-18}" width="${pw}" height="76" fill="#ffffff" fill-opacity="0" pointer-events="all"/>`;s+=group(r.record_id,`${g.title}: ${r.category}, ${r.count} of ${r.denominator}`,marks);});});$('chart').innerHTML=svg(s,w,h,'Top three reported reasons from two separate respondent groups. Each thin bar is its own zero-to-100-percent scale. Multiple answers were allowed.');key([]);$('figure-scope').textContent='November 2024 · separate user and non-user questions';$('measure-tag').textContent='Reported reasons';$('figure-note').innerHTML='<strong>Each bar runs from 0 to 100% within its group.</strong> These answers describe motivations and concerns. They do not measure actual price differences or clinical quality. Use the controls to see every reason.';}

function renderCare(w){if(state.careView==='overview'){renderCareOverview(w);return;}const table=state.careView==='users'?'5.13':'5.14',rows=DATA.survey.filter(r=>r.table===table);bars(rows,w,state.careView==='users'?C[2]:C[0]);$('figure-scope').textContent=state.careView==='users'?'181 medical-service users · reported motivations':'419 non-users of medical services · reported barriers';$('measure-tag').textContent='Up to3 answers';key([]);$('figure-note').innerHTML='<strong>Two different respondent groups.</strong> The interview study asked medical users and non-users different questions; each could select up to three reasons. Percentages describe those answers, not verified service quality or prices.';}
function providers(){return (state.year===2025?DATA.providers2025:DATA.providers2024).slice().sort((a,b)=>(state.moneyMetric==='amount'?b.claimed_hkd_thousand-a.claimed_hkd_thousand:b.claim_transactions-a.claim_transactions));}
function shortProvider(s){const names={'Shenzhen C.K.J Stomatological Hospital':'C.K.J Stomatological Hospital','Shenzhen New Frontier United Family Hospital':'New Frontier United Family','Peking University Shenzhen Hospital':'Peking University Shenzhen','Shenzhen Hospital of Southern Medical University':'Southern Medical University, SZ','Dental Bauhinia Shenzhen (combined centers)':'Dental Bauhinia · combined centres','FAH-SYSU':'Sun Yat-sen · First Affiliated','FAH-SYSU Nansha Division':'Sun Yat-sen · Nansha Division','Guangdong Provincial Hospital of Chinese Medicine':'Guangdong Chinese Medicine','Guangdong Clifford Hospital':'Guangdong Clifford','Zhongshan Hospital of Traditional Chinese Medicine':'Zhongshan Chinese Medicine','First Peoples Hospital of Foshan':'Foshan First People’s','Eighth Affiliated Hospital of Southern Medical University':'Southern Medical University · Eighth','Fifth Affiliated Hospital Sun Yat-sen University':'Sun Yat-sen · Fifth Affiliated'};return names[s]||s;}
function renderMoneyOverview(w){const small=w<500,h=485,x=12,bw=w-24,r=DATA.providers2025.find(x=>x.institution.includes('C.K.J')),amount=100*r.claimed_hkd_thousand/51811,count=100*r.claim_transactions/51384;let s=t(x,30,'C.K.J dental hospital · Shenzhen',small?15:20,'serif')+t(x,54,'One provider in a 19-provider programme',12,'muted');const rows=[{id:'share-count',title:'Share of claim transactions',p:count,caption:'22,878 of 51,384 transactions'},{id:'share-amount',title:'Share of claimed money',p:amount,caption:'HK$36.525m of HK$51.811m'}];rows.forEach((r,i)=>{const y=115+i*160;let marks=t(x,y,r.title,small?15:18)+t(x,y+43,r.p.toFixed(1)+'%',36,'serif',`style="fill:${C[3]}"`)+`<rect x="${x}" y="${y+66}" width="${bw}" height="30" fill="#ccdad4" rx="2"/><rect class="data-bar" x="${x}" y="${y+66}" width="${bw*r.p/100}" height="30" fill="${C[3]}" rx="2"/>`+t(x,y+121,r.caption,12,'muted')+`<rect x="0" y="${y-20}" width="${w}" height="148" fill="#fff" fill-opacity="0" pointer-events="all"/>`;s+=group(r.id,r.title+': '+r.p.toFixed(1)+'%',marks);});s+=t(x,473,'Gold: C.K.J · pale: the remaining share',12,'muted');$('chart').innerHTML=svg(s,w,h,'Two 100-percent bars compare the same provider’s share of transactions and claimed money in calendar 2025. They are different measures, not a time trend.');key([]);$('figure-scope').textContent='Calendar 2025 · 19 providers · unequal participation periods';$('measure-tag').textContent='Different measures';$('figure-note').innerHTML='<strong>This is concentration, not performance or profit.</strong> Twelve providers joined during 2025, and service mixes differ. Monetary shares use the published HK$51.811m total; rounded provider rows sum to HK$51.812m.';}

function renderMoney(w){if(state.moneyView==='overview'){renderMoneyOverview(w);return;}const all=providers(),rows=state.allProviders?all:all.slice(0,7),small=w<700,rowH=small?100:70,h=rows.length*rowH+55,x0=small?12:Math.min(305,w*.40),bw=small?w-110:w-x0-110,total=state.moneyMetric==='amount'?(state.year===2025?51811:19782):(state.year===2025?51384:15468);let s='';for(const tick of[0,25,50,75,100]){const x=x0+bw*tick/100;s+=`<line class="grid" x1="${x}" y1="26" x2="${x}" y2="${h-20}"/>`+t(x,16,tick+'%',12,'muted');}rows.forEach((r,i)=>{const value=state.moneyMetric==='amount'?r.claimed_hkd_thousand:r.claim_transactions,p=100*value/total,y=51+i*rowH,by=small?y+(wrap(shortProvider(r.institution),35).length>1?60:42):y-8,col=r.institution.includes('C.K.J')?C[3]:'#68878b';let row=multi(12,y,shortProvider(r.institution),small?35:24,15)+t(12,small?y+(wrap(shortProvider(r.institution),35).length>1?43:25):y+37,`${r.city} · joined ${r.start_date}`,12,'muted')+`<rect class="data-bar" x="${x0}" y="${by}" width="${(bw*p/100).toFixed(2)}" height="12" rx="1" fill="${col}" style="animation-delay:${i*.03}s"/>`+t(x0+bw+12,by+10,p.toFixed(1)+'%',20,'serif',`style="fill:${col}"`)+t(x0+bw+12,by+30,state.moneyMetric==='amount'?'HK$'+(value/1000).toFixed(3)+'m':num(value),13,'muted')+`<rect x="0" y="${y-25}" width="${w}" height="${rowH}" fill="#ffffff" fill-opacity="0" pointer-events="all"/>`;s+=group(r.institution,`${r.institution}, ${p.toFixed(1)}% of${state.moneyMetric==='amount'?'claimed money':'transactions'}, joined${r.start_date}`,row);});$('chart').innerHTML=svg(s,w,h,`${state.year} provider claims, ${state.moneyMetric==='amount'?'claimed money':'transaction count'}. Separate zero-based share bars. Participation periods differ.`);$('figure-scope').textContent=`${state.year===2025?'Calendar2025':'Inception through December2024'} · ${all.length} providers · ${rows.length<all.length?'showing7 largest recorded totals':'all providers'}`;$('measure-tag').textContent=state.moneyMetric==='amount'?'Claimed money':'Transactions';key([]);$('figure-note').innerHTML=state.year===2025?'<strong>Unequal participation periods.</strong> Twelve providers joined during2025. The published total is HK$51.811m; rounded provider rows sum toHK$51.812m. Shares use the published total. These totals are not performance, profit or health benefits.':'<strong>First-year snapshot.</strong> These seven providers joined on different dates in2024. Existing HKU–Shenzhen Hospital service points are excluded. This is not a like-for-like growth comparison with2025.';}
const allTies=[{id:'peers',label:'Peer relationships',result:'Association found',text:'Better local-peer relationships and having friends mostly from Hong Kong were associated with stronger belonging in the417-student study.',source:'ties',color:C[1]},{id:'participation',label:'Taking part',result:'Association found',text:'Extracurricular participation was associated with belonging in the same student study. The study does not prove that adding an activity causes belonging.',source:'ties',color:C[2]},{id:'commute',label:'Commuting hours',result:'No significant relationship detected',text:'Commuting hours were not statistically significant in this sample. That is not proof of no effect, and it does not establish that travel conditions are unimportant.',source:'ties',color:C[3]},{id:'wellbeing',label:'Comparative wellbeing',result:'A different question',text:'A2025 paper using2016–17 school data found little evidence of cross-border disadvantage after matching observed characteristics. Wellbeing comparisons differ from within-group belonging associations; non-significance is not equivalence.',source:'wellbeing',color:C[4]}];
const ties=allTies.filter(x=>x.id!=='wellbeing');
const questions=[{id:'money',label:'Money',result:'Where do the gains land?',text:'Follow household savings, provider receipts, public reimbursements and costs. Consumer savings, turnover and profit are different quantities.',color:C[3]},{id:'work',label:'Work',result:'Who makes it possible?',text:'Include paid work, travel, caring for someone and navigating services. Interview those who do not cross as well as those who do.',color:C[0]},{id:'voice',label:'Voice',result:'Who can influence the arrangements?',text:'Document eligibility rules, complaint routes and participation. A complaint channel is not automatically effective representation. The voucher records describe a mechanism, not its social impact.',color:C[2]}];
function renderPlans(w){const small=w<600,h=620,left=small?45:65,right=w-35,x=y=>left+(y-2026)/9*(right-left);let s=t(16,28,small?'Connections take time.':'Several centres. Different timelines.',small?23:30,'serif');['Luohu','Futian','Nanshan','Qianhai'].forEach((n,i)=>{const cx=30+i*(w-60)/3;s+=`<circle cx="${cx}" cy="87" r="7" fill="${C[1]}"/>`+t(cx,119,n,small?13:16,'',`text-anchor="middle"`);});s+=t(16,155,'Shenzhen’s four core functional centres',13,'muted')+t(16,180,'Equal markers: policy roles, not measured flows.',12,'muted');s+=`<rect x="${x(2026)}" y="225" width="${x(2030)-x(2026)}" height="330" fill="${C[1]}" opacity=".055"/>`+t(left,215,'2026–2030 plan window',12,'muted');[2027,2030,2034,2035].forEach(y=>{s+=t(x(y),small&&y===2035?598:578,String(y),12,'muted','text-anchor="middle"');});const rows=[['Kwu Tung Station',2027],['Hung Shui Kiu Station',2030],['Northern Link main + spur',2034],['Western Rail Link',2035]];rows.forEach(([name,year],i)=>{const y=265+i*77;s+=t(16,y-18,name,small?14:17)+`<line x1="${left}" y1="${y}" x2="${right}" y2="${y}" stroke="#c8d0c9"/><circle cx="${x(year)}" cy="${y}" r="7" fill="#f5f2e9" stroke="${C[3]}" stroke-width="2"/>`;});$('chart').innerHTML=svg(s,w,h,'Four Shenzhen core functional centres, and separate Hong Kong rail commissioning targets in 2027, 2030, 2034 and 2035. All timeline markers are targets.');key([]);$('figure-scope').textContent='Official planning documents · checked 8 October 2026';$('measure-tag').textContent='Targets, not outcomes';$('figure-note').innerHTML='<strong>Hollow circles = commissioning targets.</strong> These are planned connections. They do not measure current border waits, journey times, housing access or belonging.';}

function renderTies(w){if(state.tiesView==='plans'){renderPlans(w);return;}const small=w<600,findings=state.tiesView==='findings',items=findings?ties:questions,rowH=small?155:135,h=rowH*3+150;let s=t(16,32,findings?'What the student study found':'What the next fieldwork needs',small?23:30,'serif');items.forEach((it,i)=>{const y=95+i*rowH;let node=`<circle cx="24" cy="${y}" r="6" fill="${it.color}"/><line x1="24" y1="${y+17}" x2="24" y2="${y+rowH-28}" stroke="${it.color}" opacity=".3"/>`+t(45,y+5,it.label,20,'serif')+multi(45,y+35,findings?(it.id==='commute'?'No significant relationship detected':'Associated with stronger belonging'):it.result,small?27:55,15,it.color)+`<rect x="8" y="${y-26}" width="${w-16}" height="${rowH-10}" fill="#fff" fill-opacity="0" pointer-events="all"/>`;s+=group(it.id,it.label+': '+it.result,node);});if(findings){const y=rowH*3+75;const content=t(16,y,'A separate study asked about wellbeing.',small?16:20,'serif')+t(16,y+28,'Read its different question and findings →',13,'muted')+`<rect x="8" y="${y-25}" width="${w-16}" height="70" fill="#fff" fill-opacity="0" pointer-events="all"/>`;s+=group('wellbeing','Separate comparative wellbeing study',content);}$('chart').innerHTML=svg(s,w,h,findings?'Three findings about belonging from one observational study. A separate wellbeing study appears below, without a linking edge.':'Three questions for further research.');key(items.map(it=>({id:it.id,label:it.label,color:it.color})));$('figure-note').innerHTML=findings?'<strong>417 cross-border schoolchildren.</strong> Observational associations, not causal effects. The separate wellbeing study answers a different question.':'<strong>A research agenda.</strong> Money, work and influence have not been measured together for the same people here.';}

function renderInsight(){if(state.chapter===3&&state.moneyView==='overview'){const isCount=state.selected==='share-count';$('insight').innerHTML=`<div class="big">${isCount?'44.5%':'70.5%'}</div><div class="label">C.K.J’s share of ${isCount?'transactions':'claimed money'}</div><p>Both figures describe the same calendar year. A larger share of money than transactions does not establish higher prices, better care or more profit.</p>`;return;}if(state.chapter===2&&state.careView==='overview'){const r=DATA.survey.find(r=>r.record_id===state.selected&&['5.13','5.14'].includes(r.table));$('insight').innerHTML=r?`<div class="big">${pct(r.count,r.denominator)}</div><div class="label">${esc(r.category)}</div><p>${r.count} of ${r.denominator} ${r.table==='5.13'?'medical-service users':'non-users'} selected this reason. Up to three answers were allowed.</p>`:'<div class="big small">600 respondents</div><div class="label">181 medical-service users · 419 non-users</div><p>Lower costs led the users’ answers. Unfamiliarity led the non-users’ answers. A place being available does not tell us whether people feel able to use it.</p>';return;}if(state.chapter===4&&state.tiesView==='plans'){$('insight').innerHTML='<div class="big">2035</div><div class="label">Western Rail Link commissioning target</div><p>The five-year plan ends in 2030; some intended connections arrive later. A planned link does not establish a shorter journey today.</p>';return;}let big='',label='',body='';if(state.chapter===0){const p=purpose.find(p=>p.id===state.selected);big=p?p.value.toFixed(1)+'%':'74.5%';label=p?p.name:'of trips were for leisure or visiting family and friends';body=p?p.description:'The survey estimated 319,800 daily passenger movements. This is a historical 2017 trip mix, not a current count of people.';}if(state.chapter===1){if(state.peopleView==='frequency'){const g=frequencyGroups().find(x=>x.id===state.selected);big=g?`${g.count} /600`:'52.7%';label=g?g.name:'reported consumption at least monthly';body=g?g.note:'316 of the600 respondents reported at least monthly northbound consumption. This describes the interview sample.';}else{const r=DATA.survey.find(r=>r.record_id===state.selected&&r.table==='5.7');big=r?pct(r.count,r.denominator):'486';label=r?shortActivity(r.category):'northbound consumers in the sample';body=r?`${r.count} of${r.denominator} selected this activity. Multiple answers were allowed.`:'Activities overlap. The same respondent could name dining, shopping and another activity; these bars are not slices of a whole.';}}if(state.chapter===2){const tab=state.careView==='users'?'5.13':'5.14',r=DATA.survey.find(r=>r.record_id===state.selected&&r.table===tab);big=r?pct(r.count,r.denominator):state.careView==='users'?'85.1%':'51.3%';label=r?r.category:state.careView==='users'?'of users selected lower costs':'of non-users selected unfamiliarity';body=r?`${r.count} of${r.denominator} selected this reason. It is a reported motivation or concern, not a verified assessment of services.`:state.careView==='users'?'154 of 181 users selected lower costs. Each respondent could name up to three reasons; these are reported motivations, not measured savings.':'215 of 419 non-users selected unfamiliarity. Each respondent could name up to three reasons; these are reported barriers, not service-quality findings.';}if(state.chapter===3){const r=providers().find(p=>p.institution===state.selected),den=state.moneyMetric==='amount'?(state.year===2025?51811:19782):(state.year===2025?51384:15468);big=r?pct(state.moneyMetric==='amount'?r.claimed_hkd_thousand:r.claim_transactions,den):state.moneyMetric==='amount'?(state.year===2025?'HK$51.811m':'HK$19.782m'):num(den);label=r?shortProvider(r.institution):state.moneyMetric==='amount'?'published or summed claimed amount':'recorded claim transactions';body=r?`${r.city}. Joined${r.start_date}. ${num(r.claim_transactions)} transactions; HK$${(r.claimed_hkd_thousand/1000).toFixed(3)}m claimed in this period. These are not unique patients or profits.`:state.year===2025?'Calendar2025, across19 providers. Select a provider, or switch from claimed money to transaction count.':'Seven new providers, from their different2024 start dates to year end. Compare measures within this dated snapshot.';}if(state.chapter===4){const items=state.tiesView==='findings'?allTies:questions,it=items.find(x=>x.id===state.selected);big=it?it.result:state.tiesView==='findings'?'Look beyond a count.':'Ask directly.';label=it?it.label:state.tiesView==='findings'?'different evidence, different questions':'money · work · voice';body=it?it.text:state.tiesView==='findings'?'Select a relationship to see what the study supports—and what remains unresolved. The size of a node carries no statistical meaning.':'The next step is to follow actual routines and ask people about costs, relationships and influence, including those who do not cross.';}$('insight').innerHTML=`<div class="big ${big.length>19?'small':''}">${esc(big)}</div><div class="label">${esc(label)}</div><p>${esc(body)}</p>`;normalizeText($('insight'));}
function applySelection(){$('chart').querySelectorAll('[data-select]').forEach(g=>{g.classList.toggle('dim',state.selected!==null&&g.dataset.select!==state.selected);g.setAttribute('aria-pressed',String(g.dataset.select===state.selected));});$('chart-key').querySelectorAll('[data-select]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.select===state.selected)));}
function select(id){state.selected=state.selected===id?null:id;renderInsight();applySelection();const panel=$('selection-detail');panel.hidden=!state.selected;panel.innerHTML=state.selected?$('insight').innerHTML:'';}
function setChapter(i){saveScene();state.chapter=Math.max(0,Math.min(4,i));restoreScene();const target=document.querySelector(`[data-chapter-panel="${state.chapter}"]`);target.scrollIntoView({behavior:state.motion?'smooth':'auto',block:'start'});history.replaceState(null,'','#'+chapters[state.chapter].id);highlightNav();}

function table(rows,heads){return `<table class="data-table"><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function sourceHTML(id){const s=sources[id];return `<article class="source-card"><h2 id="dialog-title">${esc(s.title)}</h2><p class="source-meta">${esc(s.by)} · ${esc(s.period)}</p><p><strong>What is measured:</strong> ${esc(s.measure)}</p><p><strong>Who or what is included:</strong> ${esc(s.population)}</p><p>${esc(s.notes)}</p><p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open the original source</a>${s.extra?` · <a href="${esc(s.extra)}" target="_blank" rel="noopener noreferrer">Read the supporting source</a>`:''}</p><p class="source-meta">${esc(s.location)}</p></article>`;}
function openDialog(html){$('dialog-content').innerHTML=html;normalizeText($('dialog-content'));$('evidence-dialog').showModal();}
function methodsHTML(){return `<h2 id="dialog-title">Keep the question and the measure together.</h2><p>This is a curated visual evidence story, not a systematic review, a meta-analysis, or an estimate of the net effects of integration.</p><h3>Three different kinds of material</h3><ul><li><strong>Survey snapshots:</strong> dated answers from defined samples. Trip counts and people are not interchangeable.</li><li><strong>Administrative claims:</strong> recorded transactions in a particular programme. They do not measure profits, unique patients or clinical benefit.</li><li><strong>Observational research and questions:</strong> reported associations and a research agenda. The diagrams are not causal models or scores.</li></ul><h3>Why the views do not join into one population</h3><p>The2017 passenger survey,2024 transport-node interviews,2025 provider claims and student studies describe different people, periods and units. The interface redraws aggregates; it never follows an individual across datasets. Missing joint data stay missing.</p><h3>Corrections and rounding</h3><p>The HKFYG monthly-frequency percentage is recalculated from182/600 (30.3%); the source’s printed40.3% is retained in the data for transparency. For2025 voucher claims, the publishedHK$51.811m total is used even though rounded provider rows sum toHK$51.812m.</p><h3>Download the underlying tables</h3><p><a href="./data/hkfyg_survey.csv" download>2024 interview tables</a> · <a href="./data/dh_provider_claims_2025_annual.csv" download>2025 provider claims</a> · <a href="./data/dh_provider_claims.csv" download>2024 provider claims</a> · <a href="./data/claim_visual_contracts.json" download>Claim and scope records</a></p><p class="source-meta">Sources checked8October2026. Newer evidence may change the story. No personal records are collected or stored by this page.</p>`;}
function readingHTML(){return `<h2 id="dialog-title">Life across a border</h2><p>A text version of the visual evidence story.</p>${window.alignmentReading?window.alignmentReading():''}<h3>Four lives and a two-city synthesis</h3><p>The character selector describes overlapping analytical archetypes: weekend user, northbound relocator, cross-border commuter/student and southbound newcomer. Their portraits are illustrative. The retail and labour views retain their different populations and periods. The resilience matrix distinguishes observations, assessments and questions. All three views use ordinary readable HTML and include source links.</p><h3>1. Different reasons to cross</h3><p>The2017 pre-pandemic survey recorded319,800 average daily one-way passenger movements in both directions, by people usually living in Hong Kong, between Hong Kong and all Mainland destinations. It is not a count of unique people or a current Shenzhen-only estimate.</p>${table(purpose.map(p=>[p.name,p.value+'%']),['Purpose','Share of trips'])}<h3>2. An interview sample of600 adults</h3><p>HKFYG interviewed adults at ten transport nodes inNovember2024. This recruitment does not establish a probability sample of all residents.</p>${table(frequencyGroups().map(g=>[g.name,g.count,pct(g.count,600)]),['Consumption frequency','Respondents','Sample share'])}<h3>3. Care</h3><p>181 respondents reported using Mainland medical services;419 did not. Among users154 of181 cited lower costs. Among non-users215 of419 cited unfamiliarity. Up to three reasons could be chosen; these are reported reasons, not measured service differences.</p><h3>4. Public support</h3><p>In calendar2025,19 pilot providers recorded51,384 transactions and a publishedHK$51.811m in claims. C.K.J recorded44.5% of transactions and70.5% of claimed value. Twelve providers joined during the year. These are distributions under unequal exposure, not performance rankings.</p><h3>5. Belonging and the next questions</h3><p>A417-student observational study associated peer relationships and extracurricular participation with belonging; commuting hours were not statistically significant in that sample. A separate matched study published2025 used2016–17 data and asked different wellbeing questions. Neither establishes a universal causal effect.</p><p>Next fieldwork can ask where gains land, who carries work and costs, and who can influence the arrangements. Include people who do not cross. Hong Kong–Shenzhen is the main empirical setting; Singapore–Johor requires separate attention to its international boundary, institutions and eligibility rules.</p><h3>Places and planning</h3><p>The regional maps separate dated official planning polygons from approximate locality markers. Hong Kong development-area geography is from October 2023; the Loop outline is the 104ha statutory scheme S/LMCL/2 (2018), not the 87ha park campus. Singapore is not inside the designated land area of the Johor–Singapore Special Economic Zone.</p><p>The Hong Kong plan reports 11,000 completed Northern Metropolis domestic units in FY2021–22 to FY2025–26, with an anticipatory target of 70,000 in FY2026–27 to FY2030–31. Spade-ready land is 120ha for the earlier period versus a binding target of 900ha for the later period. These are period outputs and targets, not housing stock or verified future delivery.</p><p><a href="https://www.info.gov.hk/gia/general/202609/16/P2026091600143.htm">Hong Kong First Five-Year Plan, Major Indicators</a> · <a href="https://www.enterprisesg.gov.sg/JS-SEZ/FAQs">Enterprise Singapore: JS-SEZ scope</a> · <a href="https://www.lta.gov.sg/content/ltagov/en/newsroom/2026/10/news-releases/grantors-informed-rts-link-service-targeted-feb-2027.html">2 October 2026 RTS update: February 2027 conditional passenger-opening target</a></p><h3>Everyday access</h3><p>Official arrangements answer different questions from surveys of experience. The 2026/27 HA Shenzhen follow-up pilot has designated eligibility and providers, a RMB2,000 annual subsidy cap, and excludes inpatient and A&amp;E care; it is a different programme from elderly vouchers. For 2027 P1 admission, discretionary school applications and the two Central Allocation parts are distinct routes. Visiting permission does not itself provide employment permission. Singapore QR clearance likewise does not grant work authorisation.</p><p><a href="https://www.news.gov.hk/eng/2026/03/20260331/20260331_215256_750.html">HA follow-up pilot</a> · <a href="https://www.edb.gov.hk/attachment/en/edu-system/primary-secondary/spa-systems/primary-1-admission/EDB_P1Addendum.pdf">EDB cross-boundary P1 guidance</a> · <a href="https://www.immd.gov.hk/eng/services/visas/visit-transit/visit-visa-entry-permit.html">Hong Kong visitor conditions</a> · <a href="https://www.mom.gov.sg/passes-and-permits">Singapore work-pass information</a></p><h3>Source links</h3>${Object.entries(sources).map(([id,s])=>`<p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.by)}: ${esc(s.title)}</a></p>`).join('')}`;}

const sceneStates=[];
function saveScene(){sceneStates[state.chapter]={selected:state.selected,peopleView:state.peopleView,careView:state.careView,moneyView:state.moneyView,moneyMetric:state.moneyMetric,year:state.year,allProviders:state.allProviders,tiesView:state.tiesView};}
function restoreScene(){Object.assign(state,sceneStates[state.chapter]||{selected:null,peopleView:'frequency',careView:'overview',moneyView:'overview',moneyMetric:'amount',year:2025,allProviders:false,tiesView:'findings'});}
function activate(i){if(state.chapter!==i){saveScene();state.chapter=i;restoreScene();}}
function highlightSection(id){document.querySelectorAll('#chapter-nav [data-nav],#chapter-nav .map-nav-link').forEach(b=>{const target=b.hasAttribute('data-nav')?chapters[+b.dataset.nav].id:b.getAttribute('href').slice(1);if(target===id)b.setAttribute('aria-current','location');else b.removeAttribute('aria-current');});}
function highlightNav(){highlightSection(chapters[state.chapter].id);}
function installReadingTracker(){let pending=0,last='';const sections=[...document.querySelectorAll('[data-narrative],[data-chapter-panel],#places,#building,#access')];function update(){pending=0;const line=Math.min(180,window.innerHeight*.25);let current=sections[0];for(const section of sections){if(section.getBoundingClientRect().top<=line)current=section;else break;}if(current&&current.id!==last){last=current.id;if(current.hasAttribute('data-chapter-panel'))activate(+current.dataset.chapterPanel);highlightSection(current.id);}}function schedule(){if(!pending)pending=requestAnimationFrame(update);}window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);update();}

function clearSelection(){state.selected=null;$('selection-detail').hidden=true;$('selection-detail').innerHTML='';renderInsight();applySelection();saveScene();}
function showChapterSource(){let id=sourceKey();if(state.chapter===4&&state.selected){const it=allTies.find(x=>x.id===state.selected);if(it)id=it.source;}openDialog(sourceHTML(id));}
$('chapter-nav').addEventListener('click',e=>{const b=e.target.closest('[data-nav]');if(b)setChapter(+b.dataset.nav);});
$('story').addEventListener('click',e=>{const panel=e.target.closest('[data-chapter-panel]');if(!panel)return;activate(+panel.dataset.chapterPanel);const action=e.target.closest('[data-action]');if(action){let val=action.dataset.value;if(action.dataset.action==='year')val=+val;if(action.dataset.action==='allProviders')val=val==='true';state[action.dataset.action]=val;if(action.dataset.action==='moneyView'&&val==='overview')state.year=2025;state.selected=null;render();window.atlasAnimate?.($('chart'));saveScene();const replacement=[...$('chapter-controls').querySelectorAll('[data-action]')].find(x=>x.dataset.action===action.dataset.action&&(x.dataset.value===action.dataset.value||action.dataset.action==='allProviders'));replacement?.focus({preventScroll:true});return;}if(e.target.closest('[data-clear]')){clearSelection();return;}if(e.target.closest('[data-slot="chapter-source"]')){showChapterSource();return;}const mark=e.target.closest('[data-select]');if(mark){select(mark.dataset.select);saveScene();}});
$('story').addEventListener('keydown',e=>{const mark=e.target.closest('g[data-select]');if(mark&&(e.key==='Enter'||e.key===' ')){e.preventDefault();activate(+mark.closest('[data-chapter-panel]').dataset.chapterPanel);select(mark.dataset.select);saveScene();}});
document.querySelector('.brand').setAttribute('href','#four-lives');
$('motion-button').onclick=()=>{state.motion=!state.motion;syncMotion();};
$('sources-button').onclick=()=>openDialog('<h2 id="dialog-title">Chart sources, in context</h2><p>The periods, populations and measures belong with each finding. Map, planning and access-policy sources are also linked directly beside their views.</p>'+Object.keys(sources).map(id=>sourceHTML(id).replace(' id="dialog-title"','')).join(''));
$('method-button').onclick=()=>openDialog(methodsHTML());$('read-button').onclick=()=>openDialog(readingHTML());$('close-dialog').onclick=()=>$('evidence-dialog').close();
$('evidence-dialog').addEventListener('click',e=>{if(e.target===$('evidence-dialog')){const r=$('evidence-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('evidence-dialog').close();}});
window.addEventListener('keydown',e=>{if($('evidence-dialog').open)return;if(e.key==='Escape'){const panel=document.activeElement?.closest('[data-chapter-panel]');if(panel)activate(+panel.dataset.chapterPanel);clearSelection();}});
window.addEventListener('hashchange',()=>{const i=chapters.findIndex(c=>c.id===location.hash.slice(1));if(i>=0)setChapter(i);});
function setPageWidth(){const value=(document.documentElement.clientWidth||window.innerWidth)+'px';if(document.documentElement.style.getPropertyValue('--page-width')!==value)document.documentElement.style.setProperty('--page-width',value);}setPageWidth();window.addEventListener('resize',setPageWidth);
let resizeTimer,lastWidth=window.innerWidth;window.addEventListener('resize',()=>{if(window.innerWidth===lastWidth)return;lastWidth=window.innerWidth;clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{saveScene();const active=state.chapter;chapters.forEach((_,i)=>{state.chapter=i;restoreScene();render();});state.chapter=active;restoreScene();},200);});
function panelHTML(c,i){return `<section class="scroll-chapter" id="${c.id}" data-chapter-panel="${i}" aria-labelledby="heading-${i}"><div class="chapter-copy"><p class="eyebrow" data-slot="chapter-kicker"></p><h2 id="heading-${i}" data-slot="chapter-title"></h2><p class="lede" data-slot="chapter-lede"></p><div class="insight" data-slot="insight" aria-live="polite"></div><p class="takeaway" data-slot="chapter-takeaway"></p><button class="source-link" data-slot="chapter-source">Evidence & limitations</button></div><div class="visual-column"><div class="chapter-controls" data-slot="chapter-controls"></div><div class="figure-meta"><span data-slot="figure-scope"></span><span class="measure-tag" data-slot="measure-tag"></span></div><div class="chart" data-slot="chart"></div><div class="chart-key" data-slot="chart-key"></div><aside class="selection-detail" data-slot="selection-detail" hidden></aside><p class="figure-note" data-slot="figure-note"></p></div></section>`;}
$('story').innerHTML=chapters.map(panelHTML).join('');document.querySelector('[data-chapter-panel="1"]').after(document.getElementById('places'));document.querySelector('[data-chapter-panel="3"]').after(document.getElementById('building'));document.querySelector('[data-chapter-panel="4"]').before(document.getElementById('access'));document.getElementById('care').after(document.getElementById('trade-offs'));document.getElementById('ties').before(document.getElementById('resilience'));state.chapter=0;render();document.querySelectorAll('[data-chapter-panel]').forEach((panel,i)=>{if(i>0){panel.querySelector('[data-slot="chapter-title"]').textContent=chapters[i].title;panel.querySelector('[data-slot="chapter-lede"]').textContent=chapters[i].lede;panel.querySelector('[data-slot="chart"]').innerHTML='<p role="status">Loading the source tables…</p>';}});
(async()=>{try{const files=['hkfyg_survey.json','dh_provider_claims.json','dh_provider_claims_2025_annual.json'];const data=await Promise.all(files.map(async f=>{const r=await fetch('./data/'+f);if(!r.ok)throw new Error('data unavailable');return r.json();}));DATA={survey:data[0],providers2024:data[1],providers2025:data[2]};$('chapter-nav').innerHTML=['four-lives',0,1,'places',2,'trade-offs',3,'building','access','resilience',4].map(x=>typeof x==='number'?`<button data-nav="${x}">${chapters[x].name}</button>`:`<a class="map-nav-link" href="#${x}">${{'four-lives':'Four lives',places:'Places','trade-offs':'Trade-offs',building:'Plans',access:'Access',resilience:'Resilience'}[x]}</a>`).join('');chapters.forEach((_,i)=>{state.chapter=i;restoreScene();render();saveScene();});state.chapter=0;restoreScene();highlightNav();$('reader').innerHTML=readingHTML().replace('id="dialog-title"','id="reader-title"');syncMotion();installReadingTracker();normalizeText(document.body);document.documentElement.dataset.ready='true';const initial=chapters.findIndex(c=>c.id===location.hash.slice(1));if(initial>0)setChapter(initial);}catch(e){document.querySelectorAll('[data-chapter-panel]').forEach((panel,i)=>{if(i>0)panel.querySelector('[data-slot="chart"]').innerHTML='<p role="alert">This source table could not load. Please reload; no data have been substituted.</p>';});console.error(e);}})();
